-- Sinh tự động bởi database/cong_cu/json_sang_sql.py (--ket-qua) – kết quả 1 lần bấm "▶ Tính giá thành"
BEGIN;
SET search_path TO gia_thanh, public;
UPDATE lan_tinh SET la_hien_hanh = false WHERE cong_ty_id = (SELECT id FROM cong_ty WHERE ma = 'TH') AND la_hien_hanh;
CREATE TEMP TABLE _lt ON COMMIT DROP AS WITH x AS (
  INSERT INTO lan_tinh (cong_ty_id, ky_tu, ky_den, thoi_gian_ms, phien_ban_pm, ghi_chu) VALUES ((SELECT id FROM cong_ty WHERE ma = 'TH'), '2026-01-01', '2026-10-01', 1179, 'artifact index.html', 'Tính từ bản sao lưu 04/11/2026 (quy tắc SP lỗi 7% từ 01/2026)') RETURNING id
) SELECT id FROM x;

